import pdfplumber
import pandas as pd
import re, json
from difflib import SequenceMatcher
from pathlib import Path

pdf_path = Path('/root/invoices.pdf')
vendors_path = Path('/root/vendors.xlsx')
po_path = Path('/root/purchase_orders.csv')

vendors_df = pd.read_excel(vendors_path)
po_df = pd.read_csv(po_path)

# Build vendor lookup structures
vendors = []
for _, row in vendors_df.iterrows():
    vendors.append({
        'id': str(row['id']),
        'name': str(row['name']).strip(),
        'iban': str(row['iban']).strip(),
    })

vendor_names = [v['name'] for v in vendors]

suffixes = {'inc', 'incorporated', 'ltd', 'limited', 'corp', 'corporation', 'llc', 'co', 'company'}

def normalize(text: str) -> str:
    text = text.lower()
    text = re.sub(r'[^\w\s]', '', text)
    text = " ".join(text.split())
    # standard replacements
    text = text.replace('limited', 'ltd').replace('corporation', 'corp').replace('incorporated', 'inc')
    return text

def strip_suffixes(text: str) -> str:
    parts = text.split()
    while parts and parts[-1] in suffixes:
        parts = parts[:-1]
    return ' '.join(parts)

def similarity(a: str, b: str) -> float:
    return SequenceMatcher(None, a, b).ratio()

# Precompute normalized forms
vendor_norm = {}
for v in vendors:
    norm = normalize(v['name'])
    vendor_norm[v['name']] = {
        'norm': norm,
        'norm_stripped': strip_suffixes(norm)
    }

# PO lookup
po_lookup = {}
for _, row in po_df.iterrows():
    po_lookup[str(row['po_number']).strip()] = {
        'vendor_id': str(row['vendor_id']).strip(),
        'amount': float(row['amount'])
    }

# Matching function

def match_vendor(name: str):
    name = name.strip()
    norm = normalize(name)
    norm_stripped = strip_suffixes(norm)

    # exact match on name (case-insensitive)
    for v in vendors:
        if v['name'].lower() == name.lower():
            return v

    # exact match on normalized stripped
    for v in vendors:
        vnorm = vendor_norm[v['name']]['norm']
        vstrip = vendor_norm[v['name']]['norm_stripped']
        if norm == vnorm or norm_stripped == vstrip or norm_stripped == vnorm or norm == vstrip:
            return v

    # fuzzy match
    best = None
    best_score = 0.0
    for v in vendors:
        vnorm = vendor_norm[v['name']]['norm']
        vstrip = vendor_norm[v['name']]['norm_stripped']
        score = max(similarity(norm, vnorm), similarity(norm_stripped, vstrip))
        if score > best_score:
            best_score = score
            best = v
    if best_score >= 0.85:
        return best
    return None

# Parse invoices
