        amount = None
        iban = None
        po_number = None
        for line in text.splitlines():
            line = line.strip()
            if line.lower().startswith('from:'):
                vendor_name = line.split(':',1)[1].strip()
            elif line.lower().startswith('total'):
                # Total $XXXX.XX
                m = re.search(r'\$\s*([0-9]+(?:\.[0-9]{2})?)', line)
                if m:
                    amount = float(m.group(1))
            elif 'payment iban' in line.lower():
                iban = line.split(':',1)[1].strip()
            elif line.lower().startswith('po number'):
                po_number = line.split(':',1)[1].strip()

        invoice_data.append({
            'page': i,
            'vendor_name': vendor_name,
            'amount': amount,
            'iban': iban,
            'po_number': po_number
        })

# Evaluate fraud criteria
report = []

for inv in invoice_data:
    vendor_name = inv['vendor_name'] or ''
    amount = inv['amount']
    iban = inv['iban']
    po_number = inv['po_number']

    matched_vendor = match_vendor(vendor_name) if vendor_name else None

    reason = None
    # 1) Unknown Vendor
    if not matched_vendor:
        reason = 'Unknown Vendor'
    else:
        # 2) IBAN Mismatch
        if iban and matched_vendor['iban'] and iban.strip() != matched_vendor['iban']:
            reason = 'IBAN Mismatch'
        else:
            # 3) Invalid PO
            if not po_number or po_number not in po_lookup:
                reason = 'Invalid PO'
            else:
                po = po_lookup[po_number]
                # 4) Amount Mismatch
                if amount is None or abs(amount - po['amount']) > 0.01:
                    reason = 'Amount Mismatch'
                else:
                    # 5) Vendor Mismatch
                    if matched_vendor['id'] != po['vendor_id']:
                        reason = 'Vendor Mismatch'

    if reason:
        report.append({
            'invoice_page_number': inv['page'],
            'vendor_name': vendor_name,
            'invoice_amount': round(amount, 2) if amount is not None else None,
            'iban': iban,
            'po_number': po_number if po_number in po_lookup or po_number else None,
            'reason': reason
        })

# Write report
out_path = Path('/root/fraud_report.json')
with out_path.open('w') as f:
    json.dump(report, f, indent=2)

print('flagged', len(report))
print('output', out_path)
